	SetNpcPos("纳兰真",11,37);
	SetNpcDir("纳兰真",4);
	SetPlayerPos(12,38);
	SetPlayerDir(4);
	FadeIn();
	PlayMusic("mc018.mp3");
	Say("纳兰真：眉儿姐，你感觉好些了吗？",9);
	Say("月眉儿：真儿，谢谢你。",22);
	Say("纳兰真：眉儿姐，这草药是影枫哥刚从离忧山采来的。",9);
	Say("月眉儿：杨影枫，你虽然救了我，但是我们之间的恩怨不会从此一笔勾销的。",22);
	Say("杨影枫：……月眉儿，你知道是谁冒充飞龙堡的人绑架了真儿和蔷薇吗？",2);
	Say("月眉儿：不知道！",22);
	Say("杨影枫：我觉得这些人好像在故意制造我们之间的误会。",2);
	Say("月眉儿：原来你也不是很笨呀。",22);
	Say("杨影枫：（脸红）他们到底是谁指使的呢？",120);
	Say("月眉儿：我本来也在调查此事……但你却趁我不在跑到飞龙堡……",22);
	Say("杨影枫：（脸红）对不起……我是担心真儿……",120);
	Say("纳兰真：眉儿姐，告诉你一个秘密，你爹上官飞龙生前和我爹原本是师兄弟，他们的师父就是原来的无忧教教主月重天！",9);
	Say("月眉儿：啊！……原来你爹就是玉潜凛！",22);
	Say("杨影枫：不错……真儿的爹在加入无忧教前姓玉",2);
	Say("月眉儿：真儿……你是不是有一块玉佩？",22);
	Say("纳兰真：是啊。",9);
	Say("月眉儿：给我看一下好吗？",22);
	Say("纳兰真取下玉佩递给了月眉儿");
	Say("月眉儿：真儿……这样的玉佩我也有一块。",22);
	Say("纳兰真：是吗？真巧。",9);
	Say("月眉儿：真儿……这玉佩是不是你母亲留下来的？",22);
	Say("纳兰真：嗯，是的。",9);
	Say("月眉儿：真儿……如果没猜错的话，我们应该是亲姐妹。",22);
	Say("纳兰真：啊！？为什么？",9);
	Say("月眉儿：因为我们的母亲月明瑶在刚生下你时，发现你爹害死了你外公，于是带着我逃到了飞龙堡，以后再没回过这里。",22);
	Say("纳兰真：原来你是我的亲姐姐，怪不得我俩长得这么像呢。娘现在怎么样了？",9);
	Say("月眉儿：娘已经死了……",24);
	Say("纳兰真：啊！？娘是怎么死的？",14);
	Say("月眉儿：就是因为杨影枫他爹杨熙烈在凌绝峰比武时打死了我爹上官飞龙，娘就自杀徇情了。",24);
	Say("纳兰真：娘！……",14);
	Say("杨影枫：原来是这样，对不起……都是我爹的错……",5);
	Say("月眉儿：娘临死前对我说她在忘忧岛禁地的密室里留下了一封书信，上面写明了当时发生的一切，而这两枚玉佩就是打开密室的钥匙。",24);
	Say("杨影枫：既然这样，我和真儿去把那封书信取来……就一切都清楚了",2);
	Say("纳兰真：嗯……影枫哥",14);
	Say("月眉儿：真儿，这两枚玉佩你拿着。",22);
	Say("月眉儿把玉佩递给了纳兰真");
	Say("杨影枫：月眉儿，你先在这里休息，我和真儿去禁地走一趟，很快就回来。",2);
	Say("月眉儿：好吧。",22);
	SetNpcKind("纳兰真",3);
	Assign($Event,1814);
	Return;

@1814:
	Say("杨影枫：真儿，想不到月眉儿原来是你的亲姐姐。",2);
	Say("纳兰真：影枫哥，不知道我爹那天说的到底是不是真的。万一……",15);
	Say("杨影枫：真儿，拿到了你娘的书信，不就清楚了？",2);
	Say("纳兰真：影枫哥，我就是怕……",15);
	Return;

